import {disengage, goTo, note} from 'play';

export default Effect.gen(function* () {
  const first = yield* goTo('kepler_base').pipe(
    Effect.either
  );

  if (first._tag === 'Left') {
    if (first.left._tag === 'InBattle') {
      yield* disengage();

      const second = yield* goTo('kepler_base').pipe(
        Effect.either
      );

      if (second._tag === 'Left' && second.left._tag !== 'InBattle') {
        yield* note(second.left._tag);
      }
    } else {
      yield* note(first.left._tag);
    }
  }
});
