  const tag = (e as {_tag?: string} | null)?._tag;
  return typeof tag === 'string' ? tag : String(e);
}

export default async function main() {
  try {
    await goTo('kepler_base');
    return;
  } catch (e) {
    if (!isError(e, 'InBattle')) {
      note(errorTag(e));
      return;
    }

    await disengage();

    try {
      await goTo('kepler_base');
    } catch (e2) {
      note(errorTag(e2));
    }
  }
}
```

