import { goTo, sleep, isError } from 'play';

export default async function main() {
  let delayMs = 1000;
  let lastError: unknown;

  for (let attempt = 0; attempt < 6; attempt++) {
    try {
      return await goTo('sol_belt');
    } catch (e) {
      lastError = e;

      if (!isError(e, 'ServerBusy')) throw e;

      if (attempt < 5) {
        await sleep(delayMs);
        delayMs *= 2;
      }
    }
  }

  throw lastError;
}

