import {Effect} from 'effect';
import {disengage, goTo, note, orient, salvage, sell} from 'play';

function travel(id: string): Effect<unknown, never, 'Game'> {
  return goTo(id).pipe(
    Effect.catchTag('InBattle', () =>
      Effect.zipRight(disengage(), goTo(id))
    ),
    Effect.map((a) => a as unknown)
  );
}

function sellEverything(): Effect<unknown, never, 'Game'> {
  return Effect.gen(function* () {
    const present = yield* orient().pipe(
      Effect.catchTag('InBattle', () => Effect.zipRight(disengage(), orient()))
    );

    if (present.cargo.length > 0) {
      yield* sell(present.cargo.map((row) => ({item_id: row.item_id}))).pipe(
        Effect.catchTag('InBattle', () =>
          Effect.zipRight(disengage(),
            sell(present.cargo.map((row) => ({item_id: row.item_id})))
          )
        )
      );
    }
  }).pipe(Effect.map((a) => a as unknown));
}

export default Effect.gen(function* () {
  for (;;) {
    const result = yield* salvage().pipe(Effect.either);

    if (result._tag === 'Left') {
