import {goTo, mine, sell, service, note} from 'play';
import {orient, salvage, disengage, isError} from 'play';

export default async function main() {
  for (;;) {
    try {
      const s = await salvage();
      if (s.left.length === 0) {
        return;
      }
    } catch (e) {
      if (isError(e, 'NoWreck')) {
        note('no wreck');
        return;
      }

      if (isError(e, 'InBattle')) {
        await disengage();
        continue;
      }

      if (isError(e, 'HoldFull')) {
        await goTo('sol_base');
        const p = await orient();
        const rows = p.cargo
          .filter((r) => r.quantity > 0)
          .map((r) => ({item_id: r.item_id}));

        if (rows.length > 0) {
          const sold = await sell(rows);
          note(`sold for ${sold.total}`);
        }

        await goTo('sol_debris');
        continue;
      }

      throw e;
    }
  }
}
```

