import {orient, prices, missions, note} from 'play';

export default async function main() {
  const [present, quotes, missionList] = await Promise.all([
    orient(),
    prices(),
    missions()
  ]);

  let topId: string | null = null;
  let topBuy: number | null = null;

  for (const q of quotes) {
    if (topBuy === null || q.best_buy > topBuy) {
      topId = q.item_id;
      topBuy = q.best_buy;
    }
  }

  const topItem = topId === null ? 'none' : topId;
  note(`credits=${present.credits}; highest_best_buy=${topItem}; missions=${missionList.length}`);
}
```

