} from 'play';

type DecodedBook = {
  base: string;
  rows: readonly {
    item_id: string;
    best_buy: number;
    best_sell: number;
  }[];
};

export default async function main() {
  const present = await orient();
  const raw = await readMarket();

  let book: DecodedBook;
  try {
    book = decode(MarketBook, raw) as unknown as DecodedBook;
  } catch (e) {
    if (isError(e, 'BadData')) {
      note('bad book');
      return;
    }
    throw e;
  }

  const bestBuy = new Map<string, number>();
  for (const row of book.rows) {
    bestBuy.set(row.item_id, row.best_buy);
  }

  const toSell: { item_id: string }[] = [];
  const seen = new Set<string>();

  for (const row of present.cargo) {
    if (row.quantity <= 0) continue;
    const price = bestBuy.get(row.item_id);
    if (price === undefined || price < 10) continue;
    if (seen.has(row.item_id)) continue;

    seen.add(row.item_id);
    toSell.push({ item_id: row.item_id });
  }

  if (toSell.length > 0) {
    await sell(toSell);
  }
}

