import {missions, acceptMission, completeMissions, note, isError} from 'play';

export default async function main(): Promise<number> {
  const available = await missions();
  const wanted = available.filter((m) => m.reward >= 100);

  let accepted = 0;

  for (const mission of wanted) {
    try {
      await acceptMission(mission.id);
      accepted += 1;
    } catch (e) {
      if (isError(e, 'NoSlots')) {
        break;
      }
      throw e;
    }
  }

  try {
    await completeMissions();
  } catch (e) {
    if (isError(e, 'NothingCompletable')) {
      note('completeMissions: nothing completable');
    } else {
      throw e;
    }
  }

  return accepted;
}
