import {Effect, Either} from 'effect';
import {
  completeMissions,
  disengage,
  goTo,
  mine,
  note,
  orient,
  sell,
  service,
} from 'play';

/**
 * Runs `effect` and swallows every typed error it can produce.
 * This keeps the program going after a failure so the final
 * `orient()` + `note()` is always the last thing that happens.
 */
const safely = <A>(effect: Effect.Effect<A, unknown, never>) =>
  effect.pipe(Effect.either, Effect.map((result) => (Either.isRight(result) ? result.right : null)));

/**
 * Mine at the current belt until the hold is full.
 *
 * - `InBattle`: disengage and keep mining.
 * - `HoldFull`: stop because we are full.
 * - any other mine failure: stop and let the outer program continue/finalize.
 * - safety bounds avoid pathological infinite loops.
 */
const mineUntilFull = Effect.gen(function* () {
  let cycles = 0;
  let emptyCycles = 0;
  let battles = 0;

  while (cycles < 1_000_000) {
    const present = yield* orient();

    if (present.cargo_used >= present.cargo_capacity) {
      return {stopped: 'full' as const};
    }

    if (present.in_battle) {
      yield* disengage();
    }

    const mined = yield* mine().pipe(
      Effect.either,
    );

    if (Either.isLeft(mined)) {
      const error = mined.left;

      if (error._tag === 'InBattle') {
        battles += 1;
        if (battles > 10_000) {
          return {stopped: 'battle_loop' as const};
        }

        yield* disengage();
        continue;
      }

      if (error._tag === 'HoldFull') {
        return {stopped: 'full' as const};
      }

      return {stopped: 'error' as const};
    }

    cycles += 1;
    if (mined.right.quantity <= 0) {
      emptyCycles += 1;
      if (emptyCycles > 1_000) {
        return {stopped: 'empty' as const};
      }
    } else {
      emptyCycles = 0;
    }
  }

  return {stopped: 'safety_limit' as const};
});

const finalNote = Effect.gen(function* () {
  const here = yield* orient();
  yield* note(`credits: ${here.credits}`);
  return here.credits;
});

export default Effect.gen(function* () {
  // Head to kepler_belt. If something goes wrong, still continue to the final note.
  yield* safely(
    goTo('kepler_belt').pipe(
      Effect.catchTag('InBattle', () =>
        disengage().pipe(Effect.zipRight(goTo('kepler_belt')))
      ),
    ),
  );

  // Mine until full, recovering from pirate engagements.
  yield* mineUntilFull();

  // Head back to kepler_base.
  yield* safely(
    goTo('kepler_base').pipe(
      Effect.catchTag('InBattle', () =>
        disengage().pipe(Effect.zipRight(goTo('kepler_base')))
      ),
    ),
  );

  // Sell copper_ore. If we are not docked or there is no buyer, swallow the error.
  yield* safely(
    sell([{item_id: 'copper_ore'}]),
  );

  // Service the ship.
  yield* safely(service());

  // Complete missions, explicitly ignoring NothingCompletable.
  yield* safely(
    completeMissions().pipe(
      Effect.catchTag('NothingCompletable', () => Effect.void),
    ),
  );

  // The program's last action is always this note.
  return yield* finalNote;
});
