Here's the whole file. It runs the five steps in order: hop to the belt, run three mining cycles, fly home and dock, sell the iron_ore (omitting `quantity` sells all of it), then service. A small `fly` helper retries on `ServerBusy` (transient) before giving up, and the journal records each step.

```ts
import {Duration, Effect, Schedule} from 'effect';
import {goTo, mine, sell, service, orient, note} from 'play';

/**
 * Fly to a place, retrying across a transient ServerBusy.
 * InBattle / NoFuel / UnknownPlace are genuine dead-ends here, so let them fail.
 */
const fly = (id: string): Effect.Effect<any, any, any> =>
  goTo(id).pipe(
    Effect.retry({
      until: (e) => e._tag === 'ServerBusy',
      delay: (e: any) => Duration.fromMillis(e._tag === 'ServerBusy' ? e.retryAfterMs : 1000),
      times: 3,
      onRetry: (e, n) => note(`goTo(${id}) busy — attempt ${n + 1}`),
    }),
    Effect.map((arrived) => arrived as any),
  );

export default Effect.gen(function* () {
  // — 1. Fly to the asteroid belt —
  yield* fly('sol_belt');

  // — 2. Mine three times (one haul each, up to 10 units of iron_ore) —
  let minedTotal = 0;
  for (let cycle = 1; cycle <= 3; cycle++) {
    const take = yield* mine();
    minedTotal += take.quantity;
    yield* note(`Mine ${cycle}/3: hauled ${take.quantity} ${take.item_id}`);
  }

  // — 3. Fly back to the base and dock —
  yield* fly('sol_base');

  // — 4. Sell all the iron_ore we hold (omitting quantity = "all of it") —
  const here = yield* orient();
  const ironHeld = here.cargo
    .filter((row) => row.item_id === 'iron_ore')
    .reduce((sum, row) => sum + row.quantity, 0);

  const sold = yield* sell([{item_id: 'iron_ore'}]);
  yield* note(
    `Sold ${ironHeld} iron_ore for ${sold.total} cr` +
      (sold.short.length > 0 ? ` — unsold: ${sold.short.join(', ')}` : ''),
  );

  // — 5. Service the ship: full tank, full hull —
  const fixed = yield* service();
  const after = yield* orient();
  yield*
    note(
      `Serviced for ${fixed.cost} cr — fuel ${after.fuel}/${after.max_fuel}, hull ${after.hull}/${after.max_hull}`,
    );

  return {
    iron_mined: minedTotal,
    sold: sold.total,
    serviced: fixed,
  };
});
```

