import {Effect} from 'effect';
import {disengage, goTo, mine, note, orient, sell} from 'play';

type MineStep =
  | {kind: "mined"}
  | {kind: "full"}
  | {kind: "battle"};

function mineStep(): Effect<Unknown<typeof MineStep>, unknown, any> {
  return mine().pipe(
    Effect.map(() => ({kind: "mined" as const}) satisfies MineStep),
    Effect.catchTag("HoldFull", () => Effect.succeed({kind: "full" as const} satisfies MineStep)),
    Effect.catchTag("InBattle", () =>
      disengage().pipe(
        Effect.map(() => ({kind: "battle" as const} satisfies MineStep))
      )
    )
  );
}

export default Effect.gen(function* () {
  yield* note("mining sol_belt until hold is full");

  for (;;) {
    const step = yield* mineStep();
    if (step.kind === "full") break;
  }

  yield* note("going to sol_base");
  yield* goTo("sol_base");

  const present = yield* orient();
  const quantities = new Map<string, number>();
  for (const row of present.cargo) {
    if (row.quantity > 0) {
      quantities.set(row.item_id, (quantities.get(row.item_id) ?? 0) + row.quantity);
