    yield* note("hold is empty; nothing to sell");
    return {total: 0, fills: [], short: []};
  }

  yield* note(`selling ${items.length} item type(s) at sol_base`);
  const sold = yield* sell(items);
  yield* note(`sold for ${sold.total}`);

  return sold;
});
