import {Effect} from 'effect';
import {disengage, goTo, note, orient, salvage, sell} from 'play';

const SOL_BASE = 'sol_base';
const SOL_DEBRIS = 'sol_debris';

function salvageLoop() {
  return Effect.gen(function* () {
    yield* salvage().pipe(
      Effect.catchTag('NoWreck', () =>
        note('no wreck')
      ),
      Effect.catchTag('InBattle', () =>
        Effect.gen(function* () {
          yield* disengage();
          yield* salvageLoop();
        })
      ),
      Effect.catchTag('HoldFull', () =>
        Effect.gen(function* () {
          yield* goTo(SOL_BASE);

          const present = yield* orient();
          const rows = present.cargo.map((row) => ({item_id: row.item_id}));

          if (rows.length > 0) {
            yield* sell(rows);
          }

          yield* goTo(SOL_DEBRIS);
          yield* salvageLoop();
        })
      )
    );
  }).pipe(
    Effect.asVoid,
    Effect.ensuring(note('finished salvaging sol_debris'))
  );
}

export default Effect.gen(function* () {
  yield* salvageLoop();
});
```

