        note('no wreck');
        return;
      }

      if (isError(e, 'InBattle')) {
        await disengage();
        continue;
      }

      if (isError(e, 'HoldFull')) {
        const cleared = await clearHold();
        if (!cleared) {
          note('could not clear hold');
          return;
        }
        await returnTo('sol_debris');
        continue;
      }

      throw e;
    }
  }
