async function clearHold(): Promise<boolean> {
  await returnTo('sol_base');

  for (;;) {
    let present;
    for (;;) {
      try {
        present = await orient();
        break;
      } catch (e) {
        if (isError(e, 'ServerBusy')) {
          await sleep((e as { retryAfterMs?: number }).retryAfterMs ?? 1000);
          continue;
        }
        throw e;
      }
    }

    const rows = present.cargo
      .filter((r) => r.quantity > 0)
      .map((r) => ({ item_id: r.item_id }));

    if (rows.length === 0) return true;

    try {
      const sold = await sell(rows);
      note(`sold ${sold.total} credits`);
    } catch (e) {
      if (isError(e, 'NoBuyer')) {
        const partial = await sellPriceable();
        if (partial) return true;

        const still = await orient();
        return still.cargo_used < still.cargo_capacity;
      }

      if (isError(e, 'InBattle')) {
        await disengage();
        continue;
      }

      if (isError(e, 'NotDocked')) {
        await returnTo('sol_base');
        continue;
      }

      if (isError(e, 'ServerBusy')) {
        await sleep((e as { retryAfterMs?: number }).retryAfterMs ?? 1000);
        continue;
      }

      throw e;
    }

    const now = await orient();
    if (now.cargo_used < now.cargo_capacity) return true;
  }
}

async function sellPriceable(): Promise<boolean> {
  let quotes;
  try {
    quotes = await prices();
  } catch {
    return false;
  }

  const priceMap = new Map<string, number>();
  for (const q of quotes) {
    priceMap.set(q.item_id, q.best_buy);
  }

  const present = await orient();
  const rows = present.cargo
    .filter((r) => r.quantity > 0 && (priceMap.get(r.item_id) ?? 0) > 0)
    .map((r) => ({ item_id: r.item_id }));

  if (rows.length === 0) return false;

  try {
    const sold = await sell(rows);
    note(`sold ${sold.total} credits`);
    const now = await orient();
    return now.cargo_used < now.cargo_capacity;
  } catch {
    const now = await orient();
    return now.cargo_used < now.cargo_capacity;
  }
}

async function returnTo(id: string): Promise<void> {
  for (;;) {
    try {
      await goTo(id);
      return;
    } catch (e) {
      if (isError(e, 'InBattle')) {
        await disengage();
        continue;
      }

      if (isError(e, 'ServerBusy')) {
        await sleep((e as { retryAfterMs?: number }).retryAfterMs ?? 1000);
        continue;
      }

      if (isError(e, 'UnknownPlace')) {
        const nearest = (e as { nearest?: string }).nearest;
        if (nearest) {
          await goTo(nearest);
          continue;
        }
      }

      throw e;
    }
  }
}

