```ts
import {readMarket, orient, sell, note, decode, MarketBook, isError} from 'play';

export default async function main() {
  // Pull the raw book and decode it. A book that doesn't fit the schema is a
  // "bad book": note it and end quietly. Any other rejection is rethrown.
  let book: {
    base: string;
    rows: readonly {item_id: string; best_buy: number; best_sell: number}[];
  };
  try {
    book = decode(MarketBook, await readMarket());
  } catch (e) {
    if (!isError(e, 'BadData')) throw e;
    note('bad book');
    return;
  }

  // What are we holding right now?
  const me = await orient();

  // Sell everything whose best_buy is at least 10; keep the rest.
  // Items missing from the book have no price, so they stay in the hold.
  const bid = new Map(book.rows.map((r) => [r.item_id, r.best_buy] as const));
  const wanted = me.cargo
    .filter((row) => (bid.get(row.item_id) ?? 0) >= 10)
    .map((row) => ({item_id: row.item_id})); // quantity omitted = all of it

  if (wanted.length === 0) {
    note('nothing worth selling at 10+');
    return;
  }

  const sold = await sell(wanted);
  note(`sold for ${sold.total}; kept the rest`);
}
```

