```ts
import {readMarket, orient, sell, note, decode, MarketBook, isError} from 'play';

export default async function main() {
  let book: {base: string; rows: {item_id: string; best_buy: number; best_sell: number}[]};
  try {
    book = decode(MarketBook, await readMarket());
  } catch (e) {
    if (!isError(e, 'BadData')) throw e;
    note('bad book');
    return;
  }

  const me = await orient();
  const worth = new Map(book.rows.map(r => [r.item_id, r.best_buy]));
  const rows = me.cargo.filter(r => (worth.get(r.item_id) ?? 0) >= 10).map(r => ({item_id: r.item_id}));

  if (rows.length === 0) {
    note('nothing at 10 or more');
    return;
  }

  const sold = await sell(rows);
  note(`sold for ${sold.total}; kept the rest`);
}
```

