export default async function main() {
  const available = await missions();

  let accepted = 0;

  for (const mission of available) {
    if (mission.reward < 100) {
      continue;
    }

    try {
      await acceptMission(mission.id);
      accepted += 1;
    } catch (e) {
      if (isError(e, 'NoSlots')) {
