import {Effect, Schedule} from 'effect';
import {
  disengage,
  goTo,
  mine,
  note,
  orient,
  completeMissions,
  service,
  sell,
} from 'play';

const main = Effect.gen(function* () {
  const belt = yield* goTo('kepler_belt').pipe(
    Effect.retry(
      Schedule.recurring(750).pipe(
        Schedule.while((e) => e._tag === 'ServerBusy' || e._tag === 'InBattle'),
      ),
    ),
    Effect.catchTag('InBattle', () =>
      Effect.zipRight(disengage(), goTo('kepler_belt')),
    ),
  );

  const mineOnce = () =>
    mine().pipe(
      Effect.catchTag('InBattle', () =>
        Effect.zipRight(disengage(), mineOnce()),
      ),
    );

  while (true) {
    const mined = yield* mineOnce().pipe(Effect.either);

    if (mined._tag === 'Left') {
      if (mined.left._tag === 'HoldFull') break;
      yield* Effect.fail(mined.left);
    }

    const here = yield* orient();
    if (here.cargo_used >= here.cargo_capacity) break;
  }

  const base = yield* goTo('kepler_base').pipe(
    Effect.retry(
      Schedule.recurring(750).pipe(
        Schedule.while((e) => e._tag === 'ServerBusy' || e._tag === 'InBattle'),
      ),
    ),
    Effect.catchTag('InBattle', () =>
      Effect.zipRight(disengage(), goTo('kepler_base')),
    ),
  );

  yield* sell([{item_id: 'copper_ore'}]).pipe(
    Effect.retry(
      Schedule.recurring(750).pipe(
        Schedule.while((e) => e._tag === 'InBattle' || e._tag === 'ServerBusy'),
      ),
    ),
    Effect.catchTag('InBattle', () =>
      Effect.zipRight(disengage(), sell([{item_id: 'copper_ore'}])),
    ),
  );

  yield* service().pipe(
    Effect.retry(
      Schedule.recurring(750).pipe(
        Schedule.while((e) => e._tag === 'ServerBusy' || e._tag === 'NotDocked'),
      ),
    ),
    Effect.catchTag('NotDocked', () =>
      Effect.zipRight(goTo('kepler_base'), service()),
    ),
  );

  yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.void),
  );

  return {belt, base};
});

const finish = Effect.gen(function* () {
  const here = yield* orient();
  yield* note(`credits: ${here.credits}`);
  return here.credits;
});

export default Effect.gen(function* () {
  const result = yield* main.pipe(Effect.either);
  yield* finish;
  return result._tag === 'Right' ? result.right : null;
});

