async function safeGo(id: string): Promise<void> {
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      await goTo(id);
      return;
    } catch (e) {
      if (isError(e, 'InBattle')) {
        await disengage();
        continue;
      }

      if (isError(e, 'ServerBusy')) {
        await sleep(e.retryAfterMs);
        continue;
      }

      // Any other failure: stop trying this step, but let the program continue.
      return;
    }
  }
}

async function mineUntilFull(): Promise<void> {
  while (true) {
    try {
      await mine();
    } catch (e) {
      if (isError(e, 'HoldFull')) {
        return;
      }

      if (isError(e, 'InBattle')) {
        await disengage();
        continue;
      }

      return;
    }

    try {
      const now = await orient();
      if (now.cargo_used >= now.cargo_capacity) {
        return;
      }
    } catch {
      // If orientation fails, keep trying; the next mine will tell us the state.
    }
  }
}

async function safeSellCopper(): Promise<void> {
  try {
    const now = await orient();
    const copper = now.cargo.find((row) => row.item_id === 'copper_ore');
    if (!copper || copper.quantity <= 0) {
      return;
    }

    await sell([{ item_id: 'copper_ore' }]);
  } catch {
    // Ignore all sell failures; final credit note still happens.
  }
}

async function safeService(): Promise<void> {
  try {
    await service();
  } catch {
    // Ignore service failures.
  }
}

async function safeCompleteMissions(): Promise<void> {
  try {
    await completeMissions();
  } catch (e) {
    if (isError(e, 'NothingCompletable')) {
      return;
    }

    // Ignore all other completion failures.
  }
}

